          'Der 5-Minuten-Gedanken-Shift: 8 entlastende Sätze rund um ein Zielgefühl – ruhig, warm und komplett offline.',
        theme_color: '#f2eee4',
        background_color: '#f2eee4',
        display: 'standalone',
        lang: 'de',
        dir: 'ltr',
        start_url: '/',
        scope: '/',
        icons: [
          {
            src: 'icons/icon-192x192.png',
            sizes: '192x192',
            type: 'image/png',
            purpose: 'any maskable',
          },
          {
