// Generiert die Fokusrad-Icons (PNG 192/512, Apple-Touch 180 + SVG-Favicon)
// als echte Dateien in public/. Reines Node, ohne Abhängigkeiten:
// minimale PNG-Kodierung (RGBA, Filter "None") mit zlib.deflateSync.
import { deflateSync } from 'node:zlib'
import { mkdirSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const out = (p) => resolve(root, p)

// ---- PNG-Kodierung -------------------------------------------------------
const CRC_TABLE = Array.from({ length: 256 }, (_, n) => {
  let c = n
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1
  return c >>> 0
})

function crc32(buf) {
  let c = 0xffffffff
  for (const b of buf) c = CRC_TABLE[(c ^ b) & 0xff] ^ (c >>> 8)
  return (c ^ 0xffffffff) >>> 0
}

function chunk(type, data) {
  const len = Buffer.alloc(4)
  len.writeUInt32BE(data.length)
  const body = Buffer.concat([Buffer.from(type, 'ascii'), data])
  const crc = Buffer.alloc(4)
  crc.writeUInt32BE(crc32(body))
  return Buffer.concat([len, body, crc])
}

function encodePng(w, h, rgba) {
  const stride = 1 + w * 4
  const raw = Buffer.alloc(h * stride)
  for (let y = 0; y < h; y++) {
    raw[y * stride] = 0 // Filter: None
    rgba.copy(raw, y * stride + 1, y * w * 4, (y + 1) * w * 4)
  }
  const ihdr = Buffer.alloc(13)
  ihdr.writeUInt32BE(w, 0)
  ihdr.writeUInt32BE(h, 4)
  ihdr[8] = 8 // Bit depth
  ihdr[9] = 6 // RGBA
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ])
}

// ---- Motiv: Fokusrad -----------------------------------------------------
const BG = [241, 235, 221] // warmer Sandton (full-bleed, maskable-tauglich)
const CENTER = [250, 247, 239]
const DOT = [62, 124, 116]
const SEG_A = [168, 199, 182] // Salbei
const SEG_B = [52, 110, 99] // Tiefes Teal

const lerp = (a, b, t) => Math.round(a + (b - a) * t)
const mix = (a, b, t) => [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)]

// Farbe eines Punkts in Motiv-Koordinaten (-1..1); deckt BG zu, wenn null.
function motifColor(x, y) {
  const r = Math.hypot(x, y)
  if (r <= 0.05) return DOT
  if (r <= 0.13) return CENTER
  if (r <= 0.148) return mix(CENTER, SEG_B, 0.45) // dezente Zenterringlinie
  if (r < 0.16) return BG
  if (r <= 0.35) {
    const deg = ((Math.atan2(y, x) * 180) / Math.PI + 90 + 360) % 360
    const seg = Math.floor(deg / 45)
    const local = deg - seg * 45
    if (local < 2.2 || local > 42.8) return BG // Segment-Lücken
    return mix(SEG_A, SEG_B, seg / 7)
  }
  if (r <= 0.366) return mix(BG, SEG_B, 0.28) // sanfter Außenring-Schatten
  return null
}

function renderPng(size) {
  const rgba = Buffer.alloc(size * size * 4)
  const SS = 3 // 3x3-Supersampling für weiche Kanten
  const WEIGHTS = [0.167, 0.5, 0.833]
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      let r = 0
      let g = 0
      let b = 0
      for (const sy of WEIGHTS) {
        for (const sx of WEIGHTS) {
          const c = motifColor(((px + sx) / size) * 2 - 1, ((py + sy) / size) * 2 - 1) ?? BG
          r += c[0]
          g += c[1]
          b += c[2]
        }
      }
      const i = (py * size + px) * 4
      rgba[i] = r / 9
      rgba[i + 1] = g / 9
      rgba[i + 2] = b / 9
      rgba[i + 3] = 255
    }
  }
  return encodePng(size, size, rgba)
}

// ---- SVG-Version (favicon + Manifest-Eintrag) ----------------------------
const S = 512
const CX = S / 2
const polar = (deg, r) => [CX + r * Math.cos((deg * Math.PI) / 180), CX + r * Math.sin((deg * Math.PI) / 180)]
const fmt = (n) => n.toFixed(2)

function sector(i) {
  const a0 = -90 + i * 45 + 2.2
  const a1 = -90 + (i + 1) * 45 - 2.2
  const [x0, y0] = polar(a0, 180)
  const [x1, y1] = polar(a1, 180)
  const [x2, y2] = polar(a1, 82)
  const [x3, y3] = polar(a0, 82)
  return `M ${fmt(x0)} ${fmt(y0)} A 180 180 0 0 1 ${fmt(x1)} ${fmt(y1)} L ${fmt(x2)} ${fmt(y2)} A 82 82 0 0 0 ${fmt(x3)} ${fmt(y3)} Z`
}

function svgIcon() {
  const segs = Array.from({ length: 8 }, (_, i) => {
    const c = mix(SEG_A, SEG_B, i / 7)
    return `  <path d="${sector(i)}" fill="rgb(${c.join(' ')})"/>`
  }).join('\n')
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${S} ${S}">
  <rect width="${S}" height="${S}" fill="rgb(${BG.join(' ')})"/>
${segs}
  <circle cx="${CX}" cy="${CX}" r="68" fill="rgb(${CENTER.join(' ')})" stroke="rgb(${mix(CENTER, SEG_B, 0.45).join(' ')})" stroke-width="7"/>
  <circle cx="${CX}" cy="${CX}" r="25" fill="rgb(${DOT.join(' ')})"/>
</svg>
`
}

mkdirSync(out('public/icons'), { recursive: true })
writeFileSync(out('public/icons/icon-512x512.png'), renderPng(512))
writeFileSync(out('public/icons/icon-192x192.png'), renderPng(192))
writeFileSync(out('public/apple-touch-icon.png'), renderPng(180))
writeFileSync(out('public/icons/icon.svg'), svgIcon())
console.log('Icons erzeugt: public/icons/icon-512x512.png, icon-192x192.png, icon.svg, public/apple-touch-icon.png')

export type Mood = 1 | 2 | 3 | 4 | 5

export const SEGMENT_COUNT = 8

export const MOOD_LABELS: Record<Mood, string> = {
  1: 'Sehr belastet',
  2: 'Belastet',
  3: 'Gemischt',
  4: 'Leicht',
  5: 'Klar',
}

/** Abgeschlossenes Fokusrad (Archiv-Eintrag). */
export interface FocusWheel {
  id: string
  createdAt: string
  completedAt: string
  initialThought: string
  targetThought: string
  startMood: Mood
  endMood: Mood
  /** 8 überbrückende Sätze, alle nicht leer. */
  thoughts: string[]
}

/** Laufende (noch nicht abgeschlossene) Session – Entwurfs-Persistenz. */
export interface WheelDraft {
  id: string
  createdAt: string
  initialThought: string
  targetThought: string
  startMood: Mood
  /** 8 Slots; noch fehlende Gedanken sind ''. */
  thoughts: string[]
}

export type ThemeMode = 'light' | 'dark' | 'system'

import { SEGMENT_COUNT } from './types'
import type { FocusWheel, Mood, ThemeMode, WheelDraft } from './types'

// Versionierte localStorage-Schicht: jeder Key trägt das Schema-Version-Tag (v1).
// Alle Loader validieren und normalisieren – ungültige gespeicherte Daten
// werden verworfen oder repariert und bringen die App nie zum Absturz.
const VERSION = 'v1'

export const KEYS = {
  archive: `fokusrad:${VERSION}:archive`,
  draft: `fokusrad:${VERSION}:draft`,
  theme: `fokusrad:${VERSION}:theme`,
} as const

export const newId = (): string =>
  typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
    ? crypto.randomUUID()
    : `w-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`

const MAX_TEXT = 400

const isMood = (v: unknown): v is Mood =>
  typeof v === 'number' && Number.isInteger(v) && v >= 1 && v <= 5

const cleanText = (v: unknown): string =>
  typeof v === 'string' ? v.trim().slice(0, MAX_TEXT) : ''

/** Gedankenliste auf genau 8 Slots normalisieren; '' bleibt hier erlaubt. */
const normalizeThoughts = (v: unknown): string[] | null => {
  if (!Array.isArray(v) || v.length > SEGMENT_COUNT) return null
  const list = v.map((s) => (typeof s === 'string' ? s.trim().slice(0, MAX_TEXT) : ''))
  while (list.length < SEGMENT_COUNT) list.push('')
  return list
}

export function parseDraft(v: unknown): WheelDraft | null {
  if (!v || typeof v !== 'object') return null
  const o = v as Record<string, unknown>
  const thoughts = normalizeThoughts(o.thoughts)
  const initialThought = cleanText(o.initialThought)
  const targetThought = cleanText(o.targetThought)
  if (!thoughts || !initialThought || !targetThought) return null
  if (typeof o.id !== 'string' || !o.id || typeof o.createdAt !== 'string') return null
  if (!isMood(o.startMood)) return null
  return {
    id: o.id,
    createdAt: o.createdAt,
    initialThought,
    targetThought,
    startMood: o.startMood,
    thoughts,
  }
}

/** Abgeschlossenes Rad: alle 8 Sätze müssen gefüllt sein. */
export function parseWheel(v: unknown): FocusWheel | null {
  const base = parseDraft(v)
  if (!base) return null
  if (!base.thoughts.every((s) => s.length > 0)) return null
  const o = v as Record<string, unknown>
  if (typeof o.completedAt !== 'string' || !o.completedAt) return null
  if (!isMood(o.endMood)) return null
  return { ...base, completedAt: o.completedAt, endMood: o.endMood }
}

export function loadWheels(): FocusWheel[] {
  try {
    const raw = localStorage.getItem(KEYS.archive)
    if (!raw) return []
    const data: unknown = JSON.parse(raw)
    if (!Array.isArray(data)) return []
    return data.map(parseWheel).filter((w): w is FocusWheel => w !== null)
  } catch {
    return []
  }
}

export function saveWheels(wheels: FocusWheel[]): void {
  try {
    localStorage.setItem(KEYS.archive, JSON.stringify(wheels))
  } catch {
    // Quota-/Privacy-Fehler dürfen die App nicht stören.
  }
}

export function loadDraft(): WheelDraft | null {
  try {
    const raw = localStorage.getItem(KEYS.draft)
    if (!raw) return null
    return parseDraft(JSON.parse(raw))
  } catch {
    return null
  }
}

export function saveDraft(draft: WheelDraft | null): void {
  try {
    if (draft) localStorage.setItem(KEYS.draft, JSON.stringify(draft))
    else localStorage.removeItem(KEYS.draft)
  } catch {
    // wie oben
  }
}

export function loadTheme(): ThemeMode {
  try {
    const v = localStorage.getItem(KEYS.theme)
    return v === 'light' || v === 'dark' || v === 'system' ? v : 'system'
  } catch {
    return 'system'
  }
}

export function saveTheme(mode: ThemeMode): void {
  try {
    localStorage.setItem(KEYS.theme, mode)
  } catch {
    // wie oben
  }
}

/** Datumsformat für Archiv-Zeilen (de-DE); leer bei ungült datum. */
export function formatDate(iso: string): string {
  try {
    const d = new Date(iso)
    if (Number.isNaN(d.getTime())) return ''
    return new Intl.DateTimeFormat('de-DE', {
      day: 'numeric',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    }).format(d)
  } catch {
    return ''
  }
}

/** Kurze Verschiebungsbewertung, z. B. "+2" / "stabil" / "–1". */
export function shiftBadge(start: number, end: number): string {
  const delta = end - start
  if (delta > 0) return `+${delta}`
  if (delta < 0) return `−${Math.abs(delta)}`
  return 'stabil'
}

import { useEffect, useState } from 'react'
import { loadTheme, saveTheme } from './storage'
import type { ThemeMode } from './types'

const darkMedia = window.matchMedia('(prefers-color-scheme: dark)')

// Theme-Klassenschalter (.dark auf <html>) + theme-color-Meta-Sync,
// weil die App per Klasse (nicht per OS-Media) umstellt.
export function useTheme() {
  const [mode, setMode] = useState<ThemeMode>(() => loadTheme())

  useEffect(() => {
    saveTheme(mode)
  }, [mode])

  useEffect(() => {
    const apply = () => {
      const resolved = mode === 'system' ? (darkMedia.matches ? 'dark' : 'light') : mode
      document.documentElement.classList.toggle('dark', resolved === 'dark')
      const meta = document.querySelector('meta[name="theme-color"]')
      if (meta) meta.setAttribute('content', resolved === 'dark' ? '#161d19' : '#f2eee4')
    }
    apply()
    if (mode !== 'system') return
    darkMedia.addEventListener('change', apply)
    return () => darkMedia.removeEventListener('change', apply)
  }, [mode])

  return { mode, setMode }
}

@import "tailwindcss";

/* Dark Mode per Klassenschalter (Light/Dark/System-Toggle der App) */
@custom-variant dark (&:where(.dark, .dark *));

/* „Morgenfluss"-Palette: sanfte Teal-/Salbei- + warme Sand-/Schiefer-Töne.
   Kontrastwerte sind in Light und Dark nach WCAG AA gewählt. */
:root {
  --canvas: #f2eee4;
  --surface: #faf8f2;
  --surface-2: #ebe6d8;
  --ink: #24302b;
  --ink-soft: #55655c;
  --line: #d9d3c3;
  --accent: #2f635c;
  --accent-strong: #27544e;
  --accent-ink: #ffffff;
  --accent-soft: rgb(47 99 92 / 0.09);
  --wheel-center: #faf8f2;
  --seg-empty: #e3dcc9;
  --seg-filled: #4c7f75;
  --glow: rgb(76 127 117 / 0.35);
  --shadow-tint: rgb(70 72 56 / 0.16);
  /* Stimmungs-Punkte (decorativ, warm → teal) */
  --mood-1: #7e5f4e;
  --mood-2: #a3806a;
  --mood-3: #8e9c88;
  --mood-4: #5f8b7e;
  --mood-5: #3e7c74;
}

.dark {
  --canvas: #161d19;
  --surface: #1f2823;
  --surface-2: #2a352e;
  --ink: #e7ebe0;
  --ink-soft: #a3ae9f;
  --line: #37423b;
  --accent: #2f635c;
  --accent-strong: #3b7a70;
  --accent-ink: #ffffff;
  --accent-soft: rgb(110 158 145 / 0.14);
  --wheel-center: #1f2823;
  --seg-empty: #2b352e;
  --seg-filled: #6e9e91;
  --glow: rgb(110 158 145 / 0.3);
  --shadow-tint: rgb(6 10 8 / 0.5);
  --mood-1: #c2957e;
  --mood-2: #cfa886;
  --mood-3: #b4c2b1;
  --mood-4: #7fb3a2;
  --mood-5: #5fa392;
}

/* Runtime-Semantik-Tokens für Tailwind-Utilities (bg-canvas, text-ink, …) */
@theme inline {
  --font-sans: ui-rounded, "SF Pro Rounded", system-ui, -apple-system,
    "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  --color-canvas: var(--canvas);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-ink: var(--ink);
  --color-ink-soft: var(--ink-soft);
  --color-line: var(--line);
  --color-accent: var(--accent);
  --color-accent-strong: var(--accent-strong);
  --color-accent-ink: var(--accent-ink);
  --color-accent-soft: var(--accent-soft);
  --shadow-card: 0 10px 30px -14px var(--shadow-tint);
  --animate-rise: rise 0.45s ease-out both;
  --animate-glow: glow 2.8s ease-in-out infinite;
  --animate-soft-pulse: soft-pulse 2.2s ease-in-out infinite;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes glow {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgb(76 127 117 / 0);
  }
  50% {
    box-shadow: 0 0 26px 6px var(--glow);
  }
}

@keyframes soft-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.55;
  }
}

/* mobile-native-Baseline: kein Tap-Flash, kein Overscroll-Banding,
   16px in Inputs (gegen iOS-Auto-Zoom), sofortiges Tap-Feedback. */
html {
  background-color: var(--canvas);
  -webkit-tap-highlight-color: transparent;
  -webkit-text-size-adjust: 100%;
  overscroll-behavior: none;
}

body {
  margin: 0;
  background-color: var(--canvas);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

input,
textarea,
select {
  font-size: 16px; /*(iOS-Zoom-Ursache, nie user-scalable=no) */
}

button,
a,
[role='button'] {
  touch-action: manipulation;
}

/* Nur Steuerungselecte nicht selektierbar – Content bleibt kopierbar. */
button,
[role='button'] {
  user-select: none;
  -webkit-user-select: none;
}

/* Safe-Area-Insets (Notch/Home-Indikator; ohne viewport-fit=cover = 0) */
.safe-top {
  padding-top: env(safe-area-inset-top, 0px);
}

.safe-bottom {
  padding-bottom: calc(0.75rem + env(safe-area-inset-bottom, 0px));
}

/* Rad-Segmente: sanftes Einfärben via CSS-Transition auf fill */
.wheel-seg {
  fill: var(--seg-empty);
  transition:
    fill 700ms ease,
    opacity 700ms ease;
}

.wheel-seg-filled {
  fill: var(--seg-filled);
}

.wheel-seg-active {
  stroke: var(--accent);
  stroke-width: 1.5;
  animation: soft-pulse 2.2s ease-in-out infinite;
}

/* Gemeinsame Buttons/Cards/Felder – 8-Point-Grid, 44px-Touch-Ziele */
.btn {
  @apply inline-flex min-h-11 items-center justify-center gap-2 rounded-2xl px-4 py-3 text-[16px] font-semibold transition-[transform,background-color,border-color] duration-150 ease-out active:scale-[0.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-canvas disabled:opacity-45 disabled:pointer-events-none;
}

.btn-primary {
  @apply bg-accent text-accent-ink hover:bg-accent-strong;
}

.btn-ghost {
  @apply border border-line bg-surface text-ink hover:bg-surface-2;
}

.card {
  @apply rounded-2xl border border-line bg-surface p-4 shadow-card;
}

.input {
  @apply w-full resize-y rounded-2xl border border-line bg-surface px-4 py-3 text-[16px] leading-relaxed text-ink outline-none transition-colors duration-150 placeholder:text-ink-soft/60 focus:border-accent focus-visible:ring-2 focus-visible:ring-accent/40;
}

.chip {
  @apply inline-flex min-h-8 items-center gap-1.5 rounded-full border border-line bg-surface px-3 py-1 text-xs text-ink-soft;
}

