  /** @default false */
  strict?: boolean,
}): Promise<{}> // Notes without incoming links. strict=true: only notes with neither incoming nor outgoing links.
  - tools.obsidian.find_unresolved_links({
  /** @default null */
  vault?: string | null,
}): Promise<{}> // Links pointing to notes/files that don't exist, grouped by target.
  - tools.obsidian.get_backlinks({
  path: string,
  /** @default null */
  vault?: string | null,
}): Promise<{}> // Notes that link to or embed the given note, with line context.
  - tools.obsidian.get_daily_note({
  /** @default null */
  vault?: string | null,
  /** @default null */
  date?: string | null,
  /** @default true */
  create?: boolean,
}): Promise<{}> // Get (and by default create) the daily note for a date. Uses Obsidian's Daily Notes
  - tools.obsidian.get_outgoing_links({
  path: string,
  /** @default null */
  vault?: string | null,
}): Promise<{}> // Links and embeds in a note, each with the resolved target path (null = unresolved).
  - tools.obsidian.get_recent_notes({
  /** @default null */
  vault?: string | null,
  /** @default 20 @integer */
  limit?: number,
  /** @default null */
  folder?: string | null,
}): Promise<{}> // Most recently modified notes, newest first.
  - tools.obsidian.list_folders({
  /** @default null */
  vault?: string | null,
}): Promise<{}> // List all folders of the vault (hidden folders like .obsidian/.trash are excluded).
  - tools.obsidian.list_notes({
  /** @default null */
  vault?: string | null,
  /** @default null */
  folder?: string | null,
  /** @default true */
  recursive?: boolean,
  /** @default false */
  include_attachments?: boolean,
  /** @default 500 @integer */
  limit?: number,
}): Promise<{}> // List notes (and optionally attachments) in the vault or a folder, plus its direct subfolders.

New MCP server instructions are available in addition to those previously listed:
  <server name="obsidian">
    Use tools from this server through `execute` under `tools["obsidian"]`.
    Access to the user's Obsidian vault(s). Notes are Markdown files; paths are relative to the
    vault root (".md" is optional). Obsidian wikilinks ([[Note]], [[Note#Heading|Alias]]), tags
    (#tag, frontmatter `tags`) and YAML frontmatter are understood.

    Tips:
    - Call list_vaults first if more than one vault is configured; pass `vault` to every tool.
    - Prefer search_notes / find_notes_by_tag / get_backlinks to discover notes, then read_note.
    - For edits prefer append_to_note (optionally under a heading), replace_section, replace_in_note or
      update_frontmatter over rewriting whole notes with create_note(overwrite=true).
    - replace_in_note and replace_section accept dry_run=true to preview the change as a diff.
    - List-type results are JSON objects with a `total` count and a named list (e.g. {"total": 2, "tags": [...]}).
    - move_note keeps links intact by rewriting them in all referring notes.
    - delete_note moves notes to the vault's .trash folder unless permanent=true.
    - Every `path` parameter also accepts obsidian:// URIs, e.g. obsidian://<vault>/Folder/Note.md#Heading
      or Obsidian's own "Copy Obsidian URL" links (obsidian://open?vault=...&file=...).
    - Notes are also exposed as MCP resources (obsidian://<vault>/<path>, .daily/<date>, .tag/<tag>).
  </server>

