const CX = 110
const CY = 110
const OUTER = 98
const INNER = 64
const GAP_DEG = 2.2

const rad = (deg: number) => (deg * Math.PI) / 180
const px = (deg: number, r: number) => (CX + r * Math.cos(rad(deg))).toFixed(2)
const py = (deg: number, r: number) => (CY + r * Math.sin(rad(deg))).toFixed(2)

/** Kreissegment (Ringsektor) für Slot i, startend oben, im Uhrzeigersinn. */
function segmentPath(i: number): string {
  const a0 = -90 + i * 45 + GAP_DEG
  const a1 = -90 + (i + 1) * 45 - GAP_DEG
  return [
    `M ${px(a0, OUTER)} ${py(a0, OUTER)}`,
    `A ${OUTER} ${OUTER} 0 0 1 ${px(a1, OUTER)} ${py(a1, OUTER)}`,
    `L ${px(a1, INNER)} ${py(a1, INNER)}`,
    `A ${INNER} ${INNER} 0 0 0 ${px(a0, INNER)} ${py(a0, INNER)}`,
    'Z',
  ].join(' ')
}

/** Zielgedanke in kurze Zeilen brechen (max. 4 Zeilen im Zentrum). */
function wrap(text: string): string[] {
  const words = text.split(/\s+/).filter(Boolean)
  const lines: string[] = []
  let line = ''
  for (const word of words) {
    if (line && `${line} ${word}`.length > 16) {
      lines.push(line)
      line = word
    } else {
      line = line ? `${line} ${word}` : word
    }
  }
  if (line) lines.push(line)
  return lines.slice(0, 4)
}

interface FocusWheelSvgProps {
  thoughts: string[]
  targetThought: string
  /** Noch leerer, als nächstes gefüllter Slot – wird dezent pulsierend markiert. */
  activeIndex?: number | null
  /** Sanftes Glühen, wenn das Rad komplett ist. */
  glow?: boolean
  className?: string
}

export default function FocusWheelSvg({
  thoughts,
  targetThought,
  activeIndex,
  glow,
  className,
}: FocusWheelSvgProps) {
  const filled = thoughts.map((t) => t.trim().length > 0)
  const count = filled.filter(Boolean).length
  const lines = wrap(targetThought.trim() || 'Zielgedanke')
  const fontSize = lines.length > 3 ? 11 : 13
  const lineHeight = 15

  return (
    <div className={`rounded-full ${glow ? 'animate-glow' : ''} ${className ?? ''}`}>
      <svg
        viewBox="0 0 220 220"
        role="img"
        aria-label={`Fokusrad: ${count} von 8 Gedanken eingefärbt`}
        className="h-auto w-full"
      >
        {Array.from({ length: 8 }, (_, i) => {
          const isActive = activeIndex === i && !filled[i]
          return (
            <path
              key={i}
              d={segmentPath(i)}
              className={`wheel-seg${filled[i] ? ' wheel-seg-filled' : ''}${isActive ? ' wheel-seg-active' : ''}`}
            />
          )
        })}
        <circle
          cx={CX}
          cy={CY}
          r={INNER - 6}
          fill="var(--wheel-center)"
          stroke="var(--line)"
          strokeWidth={1.5}
        />
        <text
          x={CX}
          textAnchor="middle"
          fill="var(--ink)"
          fontSize={fontSize}
          fontWeight={600}
          dominantBaseline="middle"
        >
          {lines.map((l, i) => (
            <tspan
              key={i}
              x={CX}
              y={CY - ((lines.length - 1) * lineHeight) / 2 + i * lineHeight}
            >
              {l}
            </tspan>
          ))}
        </text>
      </svg>
    </div>
  )
}

import type { Mood } from '../types'
import { MOOD_LABELS } from '../types'

const MOODS: Mood[] = [1, 2, 3, 4, 5]

interface MoodScaleProps {
  label: string
  value: Mood
  onChange: (m: Mood) => void
}

/** Stimmungs-Skala 1–5 als tippbare Auswahl (44px+-Ziele, nicht Slider). */
export default function MoodScale({ label, value, onChange }: MoodScaleProps) {
  return (
    <div>
      <div role="group" aria-label={label} className="flex gap-2">
        {MOODS.map((m) => {
          const active = m === value
          return (
            <button
              key={m}
              type="button"
              aria-pressed={active}
              onClick={() => onChange(m)}
              className={`h-12 min-w-11 flex-1 rounded-xl border transition-[transform,border-color,background-color] duration-150 ease-out active:scale-[0.97] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent ${
                active ? 'border-accent bg-accent-soft' : 'border-line bg-surface hover:bg-surface-2'
              }`}
            >
              <span className="sr-only">
                {m}: {MOOD_LABELS[m]}
              </span>
              <span aria-hidden="true" className="mx-auto flex flex-col items-center gap-1">
                <span className="text-[17px] font-semibold leading-none tabular-nums">{m}</span>
                <span
                  className="h-2 w-2 rounded-full"
                  style={{ background: `var(--mood-${m})` }}
                />
              </span>
            </button>
          )
        })}
      </div>
      <p className="mt-2 text-sm text-ink-soft">
        {MOOD_LABELS[value]} · 1 = sehr belastet, 5 = leicht und klar
      </p>
    </div>
  )
}

import type { ReactNode } from 'react'
import type { ThemeMode } from '../types'

const svgProps = {
  viewBox: '0 0 24 24',
  fill: 'none',
  stroke: 'currentColor',
  strokeWidth: 2,
  strokeLinecap: 'round',
  strokeLinejoin: 'round',
  'aria-hidden': true,
  className: 'h-5 w-5',
} as const

const OPTIONS: { mode: ThemeMode; label: string; icon: ReactNode }[] = [
  {
    mode: 'light',
    label: 'Helles Erscheinungsbild',
    icon: (
      <svg {...svgProps}>
        <circle cx="12" cy="12" r="4" />
        <path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41" />
      </svg>
    ),
  },
  {
    mode: 'dark',
    label: 'Dunkles Erscheinungsbild',
    icon: (
      <svg {...svgProps}>
        <path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z" />
      </svg>
    ),
  },
  {
    mode: 'system',
    label: 'System Appearance folgen',
    icon: (
      <svg {...svgProps}>
        <rect x="2" y="3" width="20" height="14" rx="2" />
        <path d="M8 21h8M12 17v4" />
      </svg>
    ),
  },
]

interface ThemeToggleProps {
  mode: ThemeMode
  onChange: (m: ThemeMode) => void
}

export default function ThemeToggle({ mode, onChange }: ThemeToggleProps) {
  return (
    <div
      role="group"
      aria-label="Erscheinungsbild"
      className="flex rounded-full border border-line bg-surface p-1"
    >
      {OPTIONS.map(({ mode: m, label, icon }) => (
        <button
          key={m}
          type="button"
          aria-pressed={mode === m}
          aria-label={label}
          onClick={() => onChange(m)}
          className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-full transition-colors duration-150 active:scale-[0.94] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent ${
            mode === m ? 'bg-accent text-accent-ink' : 'text-ink-soft hover:text-ink'
          }`}
        >
          {icon}
        </button>
      ))}
    </div>
  )
}

