// Resolver-Hook: ergänzt ".ts" bei extensionslosen relativen Specifiern,
// damit Node das Vite-Bundler-Importformat der Projekt-QUelle laden kann.
export async function resolve(specifier, context, nextResolve) {
  if ((specifier.startsWith('./') || specifier.startsWith('../')) && !/\.[a-z]+$/.test(specifier)) {
    try {
      return await nextResolve(specifier + '.ts', context)
    } catch {
      //Fallback unten
    }
  }
  return nextResolve(specifier, context)
}

// One-off Speicher-Layer-Check (outside the artifact folder):
// stubs localStorage, loads src/storage.ts straight via the resolver hook.
const store = new Map()
let throwOnWrite = false
globalThis.localStorage = {
  getItem: (k) => (store.has(k) ? store.get(k) : null),
  setItem: (k, v) => {
    if (throwOnWrite) throw new Error('QuotaExceededError (sim)')
    store.set(k, String(v))
  },
  removeItem: (k) => store.delete(k),
}

const S = await import('file:///Users/cedi/Clouds/Projekte/KI/LLM-Bench/tests/fokusrad-mini/Qwen3.8-Flash-Next-oQ2.5e-fp16-mtp/src/storage.ts')

const failures = []
const check = (name, cond) => { if (!cond) failures.push(name) }

const filled = (n) => Array.from({ length: 8 }, (_, i) => (i < n ? `s${i}` : ''))
const validWheel = {
  id: 'w1', createdAt: 'c1', completedAt: 't1',
  initialThought: 'last', targetThought: 'light',
  startMood: 2, endMood: 4, thoughts: filled(8),
}
const validDraft = {
  id: 'w2', createdAt: 'c2',
  initialThought: 'last', targetThought: 'light',
  startMood: 3, thoughts: filled(3),
}

// 1) clean slate
check('empty loadWheels', JSON.stringify(S.loadWheels()) === '[]')
check('empty loadDraft', S.loadDraft() === null)
check('default theme', S.loadTheme() === 'system')

// 2) broken JSON must never crash
store.set(S.KEYS.archive, '{not-json')
store.set(S.KEYS.draft, 'garbage!!')
check('broken archive', S.loadWheels().length === 0)
check('broken draft', S.loadDraft() === null)
store.delete(S.KEYS.archive)
store.delete(S.KEYS.draft)

// 3) mixed archive keeps valid, drops invalid
store.set(S.KEYS.archive, JSON.stringify([validWheel, { ...validWheel, endMood: undefined }, 'nope', null, { ...validWheel, id: 'w3', thoughts: filled(7) }, validWheel]))
check('mixed archive → 2 valid', S.loadWheels().map((w) => w.id).join(',') === 'w1,w1')

// 4) non-array archive
store.set(S.KEYS.archive, JSON.stringify({ not: 'array' }))
check('non-array archive', S.loadWheels().length === 0)

// 5) draft normalization: pad to 8, non-string → '', cap 400
store.set(S.KEYS.draft, JSON.stringify({ ...validDraft, thoughts: ['x', 42, ' y '] }))
const d = S.loadDraft()
check('draft padded', d !== null && d.thoughts.length === 8 && d.thoughts.join('|') === 'x||y||||||')
store.set(S.KEYS.draft, JSON.stringify({ ...validDraft, initialThought: 'ä'.repeat(500) }))
check('text capped 400', S.loadDraft().initialThought.length === 400)

// 6) draft validation
check('draft missing target', S.parseDraft({ ...validDraft, targetThought: '  ' }) === null)
check('draft bad mood', S.parseDraft({ ...validDraft, startMood: 6 }) === null)
check('draft bad id', S.parseDraft({ ...validDraft, id: '' }) === null)
check('draft too many thoughts', S.parseDraft({ ...validDraft, thoughts: filled(9).concat(['extra']) }) === null)

// 7) wheel validation: incomplete / missing endMood rejected
check('wheel incomplete', S.parseWheel({ ...validWheel, thoughts: filled(7) }) === null)
check('wheel missing endMood', S.parseWheel({ ...validWheel, endMood: '4' }) === null)
check('wheel valid passes', S.parseWheel(validWheel).endMood === 4)

// 8) save round-trips incl. null clearing + theme
S.saveWheels([validWheel])
check('saveWheels round-trip', JSON.parse(store.get(S.KEYS.archive))[0].id === 'w1')
S.saveDraft(validDraft)
check('saveDraft round-trip', S.loadDraft().id === 'w2')
S.saveDraft(null)
check('saveDraft(null) clears', !store.has(S.KEYS.draft))
S.saveTheme('dark')
check('theme dark', S.loadTheme() === 'dark')
store.set(S.KEYS.theme, 'blau')
check('theme invalid → system', S.loadTheme() === 'system')

// 9) quota/privacy write errors must be swallowed
throwOnWrite = true
check('saveWheels swallows quota', (() => { try { S.saveWheels([validWheel]); return true } catch { return false } })())
check('saveDraft swallows quota', (() => { try { S.saveDraft(validDraft); return true } catch { return false } })())
check('saveTheme swallows quota', (() => { try { S.saveTheme('light'); return true } catch { return false } })())
throwOnWrite = false

// 10) newId
check('newId string', typeof S.newId() === 'string' && S.newId().length > 3)

if (failures.length) {
  console.log(`FAIL ${failures.length}: ${failures.join(', ')}`)
  process.exitCode = 1
} else {
  console.log('STORAGE-OK: alle 25 Prüfungen bestanden')
}

